import java.nio.file.*; import java.util.*; import java.io.*;
public class FilesProbe { public static String rows() throws Exception { Path d=Files.createTempDirectory("decaf-oracle-"); Path sub=d.resolve("sub"); Path p=sub.resolve("x.txt"); List<String> r=new ArrayList<>(); r.add("dir0="+Files.exists(sub)); Files.createDirectories(sub); r.add("dir1="+Files.exists(sub)+",isDir="+Files.isDirectory(sub)+",isReg="+Files.isRegularFile(sub)+",read="+Files.isReadable(sub)+",sym="+Files.isSymbolicLink(sub)+",exec="+Files.isExecutable(sub)); Files.writeString(p,"hello"); r.add("file="+Files.exists(p)+",isDir="+Files.isDirectory(p)+",isReg="+Files.isRegularFile(p)+",read="+Files.isReadable(p)+",sym="+Files.isSymbolicLink(p)+",exec="+Files.isExecutable(p)+",text="+Files.readString(p)); r.add("list="+Files.list(sub).map(x->d.relativize(x).toString()).sorted().toList()); Files.delete(p); r.add("afterDelete="+Files.exists(p)+",not="+Files.notExists(p)); Path m=d.resolve("missing"); r.add("missing="+Files.exists(m)+",not="+Files.notExists(m)+",read="+Files.isReadable(m)+",sym="+Files.isSymbolicLink(m)+",exec="+Files.isExecutable(m)); return String.join("\\n",r); } public static void main(String[] a)throws Exception{System.out.print(rows());}}
